//! Tier 2's range checks (spec §11 GR-11), called from `props_check.rs`'s
//! `check_video`: each wheel's `x`, `y` and `master` −1…1, and its push
//! inside the unit circle; and each curve's 2–16 points, x and y 0…1, x
//! strictly rising (GR-12), a hue curve's x 0 ≤ x < 360 and its value in
//! its domain's range (GR-32); and the qualifier's ranges, each bound in its
//! own sentence and low ≤ high (GR-13), then its `blur` 0…1 (GR-35).
//!
//! The rule is `props_check.rs`'s: a value out of range is NAMED in the
//! rule's own sentence, never clamped (an action's end is clamped instead,
//! by `actions_clamp_grade.rs`'s `clamp_wheels`). The circle test allows
//! [`WHEEL_RIM_TOLERANCE`] past 1, so a rim point made by `cos`/`sin` or
//! divided by its `hypot` — the inspector's puck and `clamp_wheels` both
//! make one — is never refused; the sentence still says `≤ 1`.

use crate::model::{
    CurveDomain, Curves, Qualifier, Wheels, CURVE_POINTS_MAX, CURVE_POINTS_MIN, HUE_SOFTNESS_MAX,
    HUE_TURN, QUALIFIER_BLUR_MAX, WHEEL_MAX, WHEEL_RIM_TOLERANCE,
};
use crate::props_check::in_range;

/// `Ok` when every wheel is in range and inside the circle; the first
/// refusal otherwise, in model order (lift, gamma, gain; x, y, master).
pub(crate) fn check_wheels(wheels: &Wheels) -> Result<(), String> {
    for (name, wheel) in wheels.named() {
        let key = format!("video.wheels.{name}");
        in_range(&format!("{key}.x"), wheel.x, -WHEEL_MAX, WHEEL_MAX)?;
        in_range(&format!("{key}.y"), wheel.y, -WHEEL_MAX, WHEEL_MAX)?;
        in_range(
            &format!("{key}.master"),
            wheel.master,
            -WHEEL_MAX,
            WHEEL_MAX,
        )?;
        if wheel.x * wheel.x + wheel.y * wheel.y > 1.0 + WHEEL_RIM_TOLERANCE {
            return Err(format!(
                "{key} must lie inside the unit circle (x² + y² ≤ 1), not x {}, y {}",
                wheel.x, wheel.y
            ));
        }
    }
    Ok(())
}

/// `Ok` when every curve holds 2–16 points, each x and y 0…1 (bounds
/// inclusive) and x strictly rising; the first refusal otherwise, in model
/// order (master, red, green, blue, hue_hue, hue_sat), then point order,
/// indices 0-based (GR-12). A hue curve's x is 0 ≤ x < 360 and its value
/// within its domain's range (GR-32). An identity curve passes: `set_video`
/// drops it after this.
pub(crate) fn check_curves(curves: &Curves) -> Result<(), String> {
    for (name, domain, curve) in curves.named() {
        let Some(points) = curve else {
            continue;
        };
        let key = format!("video.curves.{name}");
        if !(CURVE_POINTS_MIN..=CURVE_POINTS_MAX).contains(&points.len()) {
            return Err(format!(
                "{key} needs {CURVE_POINTS_MIN} to {CURVE_POINTS_MAX} points, not {}",
                points.len()
            ));
        }
        let (low, high) = domain.value_range();
        for (index, point) in points.iter().enumerate() {
            if domain == CurveDomain::Tone {
                in_range(&format!("{key}[{index}].x"), point[0], 0.0, 1.0)?;
            } else if !(point[0].is_finite() && point[0] >= 0.0 && point[0] < HUE_TURN) {
                return Err(format!(
                    "{key}[{index}].x must be at least 0 and below {HUE_TURN}, not {}",
                    point[0]
                ));
            }
            in_range(&format!("{key}[{index}].y"), point[1], low, high)?;
            if index > 0 && point[0] <= points[index - 1][0] {
                return Err(format!(
                    "{key}[{index}].x ({}) must be greater than {key}[{}].x ({})",
                    point[0],
                    index - 1,
                    points[index - 1][0]
                ));
            }
        }
    }
    Ok(())
}

/// `Ok` when every present range is inside its bounds (all inclusive, spec
/// §11 GR-13): the hue's `center` and `width` 0…360 and its `softness`
/// 0…180; each level range's `low`, `high` and `softness` 0…1 and `low ≤
/// high`. The first refusal otherwise, in the order hue (centre, width,
/// softness), saturation (low, high, softness, then the order), luma the
/// same; then `blur` 0…1 (GR-35), last. A bound is compared exactly, so
/// 360, 180, 0 and 1 all pass.
pub(crate) fn check_qualifier(qualifier: &Qualifier) -> Result<(), String> {
    if let Some(hue) = &qualifier.hue {
        in_range("video.qualifier.hue.center", hue.center, 0.0, HUE_TURN)?;
        in_range("video.qualifier.hue.width", hue.width, 0.0, HUE_TURN)?;
        in_range(
            "video.qualifier.hue.softness",
            hue.softness,
            0.0,
            HUE_SOFTNESS_MAX,
        )?;
    }
    for (name, range) in qualifier.levels() {
        let Some(range) = range else {
            continue;
        };
        let key = format!("video.qualifier.{name}");
        in_range(&format!("{key}.low"), range.low, 0.0, 1.0)?;
        in_range(&format!("{key}.high"), range.high, 0.0, 1.0)?;
        in_range(&format!("{key}.softness"), range.softness, 0.0, 1.0)?;
        if range.low > range.high {
            return Err(format!(
                "{key}.low ({}) must not be greater than {key}.high ({})",
                range.low, range.high
            ));
        }
    }
    in_range(
        "video.qualifier.blur",
        qualifier.blur,
        0.0,
        QUALIFIER_BLUR_MAX,
    )
}
//! The grading clamps `clamp_video` runs on an action's evaluated video props: the wheels, the
//! curves and the qualifier, each bounded as its own doc says.
//! A pure move out of `actions_clamp.rs` under road map "creator-jobs" CU0a's toll U5.

use crate::actions_clamp::bounded;
use crate::model::{
    CurveDomain, CurvePoint, Curves, HueRange, LevelRange, Qualifier, Wheels, CURVE_POINTS_MAX,
    CURVE_POINTS_MIN, HUE_SOFTNESS_MAX, HUE_TURN, QUALIFIER_BLUR_MAX, WHEEL_MAX,
};

/// The wheels (spec §11 GR-11): a NaN to 0, each value to ±1, and a push
/// outside the unit circle divided by its `hypot` onto the rim — a point
/// `grade_check.rs`'s circle test always takes (its `WHEEL_RIM_TOLERANCE`).
pub(crate) fn clamp_wheels(wheels: &mut Wheels) {
    for wheel in [&mut wheels.lift, &mut wheels.gamma, &mut wheels.gain] {
        wheel.x = bounded(wheel.x, -WHEEL_MAX, WHEEL_MAX, 0.0);
        wheel.y = bounded(wheel.y, -WHEEL_MAX, WHEEL_MAX, 0.0);
        wheel.master = bounded(wheel.master, -WHEEL_MAX, WHEEL_MAX, 0.0);
        if wheel.x * wheel.x + wheel.y * wheel.y > 1.0 {
            let radius = wheel.x.hypot(wheel.y);
            wheel.x /= radius;
            wheel.y /= radius;
        }
    }
}

/// The curves (spec §11 GR-12): each x and y to 0…1, a channel holding a
/// NaN removed; a channel with fewer than 2 or more than 16 points, or whose
/// x's do not strictly rise after the clamp, removed; then every identity
/// channel removed, so an action that ends on the identity ends uncurved.
/// A hue curve (GR-32) clamps its x's to 0…360 and is removed when its last
/// x is 360, and its values to its domain's range.
pub(crate) fn clamp_curves(curves: &mut Curves) {
    for (domain, curve) in curves.named_mut() {
        if let Some(points) = curve.as_mut() {
            if !clamp_points(points, domain) {
                *curve = None;
            }
        }
    }
    curves.drop_identities();
}

/// One channel's points clamped in place; false when the channel must go.
fn clamp_points(points: &mut [CurvePoint], domain: CurveDomain) -> bool {
    if !(CURVE_POINTS_MIN..=CURVE_POINTS_MAX).contains(&points.len()) {
        return false;
    }
    let x_high = if domain == CurveDomain::Tone {
        1.0
    } else {
        HUE_TURN
    };
    let (low, high) = domain.value_range();
    for point in points.iter_mut() {
        if point.iter().any(|value| value.is_nan()) {
            return false;
        }
        point[0] = point[0].clamp(0.0, x_high);
        point[1] = point[1].clamp(low, high);
    }
    if domain != CurveDomain::Tone && points.last().is_some_and(|last| last[0] >= HUE_TURN) {
        return false;
    }
    points.windows(2).all(|pair| pair[1][0] > pair[0][0])
}

/// The qualifier (spec §11 GR-13): a range holding a NaN removed; every
/// other number to its bounds — the hue's width 0…360 and softness 0…180,
/// each level 0…1 — the hue centre taken `rem_euclid 360` (so a centre an
/// action moved past 360 or below 0 on the short way round,
/// `actions_qualifier.rs`, comes back onto the circle), and a level range
/// whose `low` passed its `high` closed at `high = low`. The `blur` (GR-35):
/// non-finite → 0, then 0…1.
pub(crate) fn clamp_qualifier(qualifier: &mut Qualifier) {
    if let Some(hue) = qualifier.hue {
        qualifier.hue = clamp_hue(hue);
    }
    for range in [&mut qualifier.saturation, &mut qualifier.luma] {
        if let Some(level) = *range {
            *range = clamp_level(level);
        }
    }
    qualifier.blur = if qualifier.blur.is_finite() {
        qualifier.blur.clamp(0.0, QUALIFIER_BLUR_MAX)
    } else {
        0.0
    };
}

/// One hue range clamped, or `None` when it must go.
fn clamp_hue(hue: HueRange) -> Option<HueRange> {
    if !hue.center.is_finite() || hue.width.is_nan() || hue.softness.is_nan() {
        return None;
    }
    Some(HueRange {
        center: hue.center.rem_euclid(HUE_TURN),
        width: hue.width.clamp(0.0, HUE_TURN),
        softness: hue.softness.clamp(0.0, HUE_SOFTNESS_MAX),
    })

