            }.count
            menuItem?.state = carrying == 0 ? .off : (carrying < targets.count ? .mixed : .on)
        } else if let tagged = lookKind(menuItem?.tag ?? Int.min) {
            let carrying = targets.filter { $0.videoProps.look?.kind == tagged }.count
            menuItem?.state =
