import subprocess
from pathlib import Path

REPO = Path("/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs")
DOCS = "docs/site/src/content/docs"
pages = sorted(
    str(p.relative_to(REPO))
    for pattern in ("color/*.mdx", "hdr/*.mdx", "mcp/tools-set-video.mdx")
    for p in (REPO / DOCS).glob(pattern)
)
for command in (
    ["node", "docs/site/scripts/check-pages.mjs", *pages],
    ["python3", "tools/proof/docs_site_proof.py", "--pages", *pages],
):
    done = subprocess.run(command, cwd=REPO, capture_output=True, text=True)
    print(command[1], "exit", done.returncode)
    print((done.stdout + done.stderr)[-1200:])
